  VALUES 
    (496::BIGINT, 'Es el mejor profe de mate que va a tener en su vida, explica muy claro, los ejercicios quices son muy parecidos a los exámenes y siempre busca ayudarlo a uno. Si tiene oportunidad de matricular con él hágalo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, '86284c6af36fe8257889da0adcad76931ff9dbc7317dd465fca34c583baf8503'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Mae vea ignore todos esos comentarios raros que le salen. Es el mejor profesor de matemática que usted va a tener en su vida. Asi de simple.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'eb3aa024a3e2ed4db845a130e5d66265db1bc7faad4fd180a20f0f4678ec80b3'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es increíble, si quiere pasar estadística vaya con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'ed539cf6238b5580421ea88cfbe3828ce50c6341842955927a61cc4ad5436ee1'::TEXT, ARRAY[1057]::BIGINT[]),
    (496::BIGINT, 'El mejor profe. En la clase resuelve y da tips para ejercicios más difíciles a los del examen, pero no se extiende mucho. Tiene ejercicios y prácticas que ayudan un montón para las evaluaciones y califica suave.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'efb441575442983b7410c020017135b1da9aa0b9ebb8b94c4bbceb89dda109fb'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Un Dios, de los mejores de profe de mate.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-13T00:00:00+00:00'::TIMESTAMPTZ, '3c32a18df9e90727493f67490ad5e594538fe07a43a3cf71a3999358ef327904'::TEXT, ARRAY[1057]::BIGINT[]),
    (496::BIGINT, 'Es un muy buen profe, si tiene la oportunidad de meter un curso con el no tenga duda El profe responde las dudas y si hace los ejercicios recomendados le va ir muy bien En los exámenes no califica tan duro'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-10T00:00:00+00:00'::TIMESTAMPTZ, '95d770566689e711b8e46fe9bf033e835d93a34c60e194625d7677edbfbf1e2c'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Masis es un Dios lo amo Es el mejor profe del mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-01-09T00:00:00+00:00'::TIMESTAMPTZ, '7926acaeb14141a3610d53d0a998e79093a5fa42ec865551196e744aa68aee4c'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'No le haga caso a los comentarios intentando desprestigiar al profe Masis. Él es un excelente profe y siempre fue bastante respetuoso y buena nota en las clases. Hizo muy chill el curso de métodos numéricos ya que la mayoría de trabajos eran programaciones sencillas en grupos. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-03T00:00:00+00:00'::TIMESTAMPTZ, '4127e032ef901d924c84d8a9a75180e4908ac91fe5a7bea0d79b1f2189836389'::TEXT, ARRAY[968]::BIGINT[]),
    (496::BIGINT, 'Un excelente profesor, super recomendado. El profe tiene prácticas aparte que le ayudan demasiado a uno para los exámenes y quices, de verdad solo estudiando las prácticas le va bien para pasar. Siempre le va contestar sus dudas tanto por mensaje como en consulta o al final de la clase.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-12-02T00:00:00+00:00'::TIMESTAMPTZ, '3f6a168be995274feded8f1b4b93c2c6d6ee140476b504664a90a63853d45ea8'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b0cde8dc308dc81acce5fd55e64baa14d59f1da505283cc16b5f2c19fe5f5006'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Excelente profe, básicamente enseña lo que evalúa tanto en quices como en exámenes, la clase se vuelve solo calidad y no se extiende mucho. Dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2024-11-27T00:00:00+00:00'::TIMESTAMPTZ, 'b6db05cd134be2aa3d8a37be8048b151e1867cb80844788eca133bea8a194021'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Simplemente el mejor profesor del Tec, si puede matricular con él, no lo piense, con solo ir ya pasa sobrado, los quices son de ejercicios ya vistos, da buena práctica para el examen y la explicación es excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'c5286cf60a252e265b9ae11cc5cbdf0e784f727d011ea7503f46fab580fbf570'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Excelente profe, si tiene la oportunidad no dude en matricular con él. La materia queda super clara, las prácticas son muy similares a lo evaluado en quices y en el examen. Revisa super rápido todas las entregas. Super recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '10e7ee68c2db797b53a49cbab3b031f39b916f2a5ceced74508c747153a66be9'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Si tiene la oportunidad matricule con él, las explicaciones son demasiado buenas y siempre da muchísimo apoyo. Excelente profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'a8c88f0b6c441a673230fdb1a7dd8e1533a6b96c535eef7cce5290535ae36de1'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'La materia se entiende perfectamente, va al grano en la clase y aun así no se hace pesada. Las prácticas que deja son muy similares a los exámenes y quices. Sin duda el mejor profe para superior, cualquiera que diga lo contrario es porque se lo sonaron ( y se los dice un sonado)'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'd91ed6c2b472cb320d76e6cffcfd82f7133133197df0bae890cfa14a44d73572'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Es el mejor profe de mate que he tenido, es súper buena persona, si usted hace los ejercicios recomendados los quices se hacen solos, y los simulacros ayudan muchísimo, explica super bien y claramente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Inspirador', 'Clases excelentes']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '1a0a5f189b0fcf53fa5f78c571f2925f8c81673f6b79c9632aace2381b498628'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es un poco vulgar para hablar, como persona es bueno y ayuda mucho a con los simulcros, que es casi la misma vara que el examen, pero los quices los hace macabros, entonces si no estudia, él lo fusila en los quices y aunque no es el mejor, medio se la juega, entonces si no hay nada, dele con él'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Clases largas']::TEXT[], '2024-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'f0e0d697944ae2de3bcbdd464cd42ad1a3327bc6fc44cbae391a90ac1e568183'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es un excelente profesor, explica muy bien, resuelve dudas rápidamente y es muy comprensivo. Hay muchos comentarios mal intencionados que solo pretenden desacreditarlo. Téngalo dentro de sus primeras opciones para este curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-01-25T00:00:00+00:00'::TIMESTAMPTZ, '8ac5b9bfb61ccb80ac843836d5b837f654d4522aa12c2737927e5543376f658a'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor profe que he tenido en la vida. Es muy claro, da buenos tips, ayuda las veces que sea necesario y es muy ordenado. Además, es una persona maravillosa: amable, dispuesto a ayudar y gracioso. El curso tiene su buena complejidad, pero vaya a todas las clases de Masís y se pasa perfectamente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-12-02T00:00:00+00:00'::TIMESTAMPTZ, '260e11935e355ea39d83997df746a1586a460e8f85632a1cf91d7ecc09e41d07'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Las clases son excelentes, muy de acuerdo al nivel del examen. Es muy comprensivo y siempre está dispuesto a ayudar. De vez en cuando tira comentarios graciosos.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-11-13T00:00:00+00:00'::TIMESTAMPTZ, '2e724bb3fb0758081b81a2fd862b96fd38f9784c96e1090f73cc789ea03b115b'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Buen Profe.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-07-17T00:00:00+00:00'::TIMESTAMPTZ, '6446263ef1dac631740bc11e89c9536c36a5837a3cd3903c441b5a54ddfd69b5'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Muy buen profesor, con lo que explica en clase es suficiente para entender la materia, los quices no son complicados y está dispuesto a ayudar tanto en clases como en consulta. Masis God.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '7dc7a7e0241befa5782fbe9aa8c8af270f9ac2ca0fe68185e5d3f652439114f9'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El Dios Masis, súper recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '62121df639ac8c52796b8f0f80f81972814d798cddd4351213bc80d9461c6f5f'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Es un profe excelente y dedicado, sus clases son entretenidas y esta siempre dispuesto a brindar ayuda, es el mejor profe de mate del TEC'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '605848b0dd9e6c871018e5bf2fc57a1ea3a8765c26bb5adce73ec8f48342308e'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor profe de mate que he tenido, no haga caso a los comentarios negativos el profe es muy bueno explica súper claro y las veces que sea necesario. Si tienen la oportunidad de matricular con él háganlo de fijo.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, '686359794b68eb7d63184350d3eb8c69713ae6266c379ff3a3687374168ff894'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor, explica muy claro. Muchas personas dicen que se c**ea a media clase pero no puedo decir que sea cierto. Es medio coqueto con las mujeres pero de eso a que se las levante ya son otros 100 pesos, lo haga o no, es muy buen profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '6d8a2869f722998350b5300a10cf6850c885a5c284b9312cf89cf32a62f34400'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Es excelente, explica demasiado bien, siempre dispuesto ayudar al estudiante, los quices que hace son sencillos y las prácticas que deja preparan bastante para los parciales. Es un pro, definitivamente Masis God'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-10T00:00:00+00:00'::TIMESTAMPTZ, 'bacf5f22e8da6f3ee627e8c328a65cf5a34572542fedefdf24e423fda99c7dbb'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor, explica con claridad y las evaluaciones tienen un nivel adecuado (son bastantes). Es amable, siempre dispuesto a aclarar dudas y brindar ayuda.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Brinda apoyo']::TEXT[], '2022-12-02T00:00:00+00:00'::TIMESTAMPTZ, '416fe0871e7dc83fdcaa0a952cf331b278e91269b4cbc8bbc5c1d11d5b0adaf1'::TEXT, ARRAY[968]::BIGINT[]),
    (496::BIGINT, 'Definitivamente el mejor profe de la escuela de mate con el que me he encontrado. Las clases son super livianas y pocas veces se hacen aburridas. El profe ayuda montones y califica suave, prepara super bien para los parciales. No hagan caso a los comentarios negativos sobre él, son falsos.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '1dddcd0b2f05b437e75d8ad84bae6b6f1bd3f2de6bd7c2855eb10d10432c290f'::TEXT, ARRAY[1672]::BIGINT[]),
    (496::BIGINT, 'Soy mujer, es lo primero que quiero decir Lo segundo que quiero decir es que Masís es un excelente profe, si usted es una mae que es tan idiota y cortita como para confundir la amabilidad y ayuda con ligoteo es su problema, medíquese, pero sepan que el profe es siempre respetuoso con TODOS'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Respetado por los estudiantes']::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, '99357143ee09162e6313f51138da09b3d12f6bd01edc940c2a36102f524d8d70'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'Hola personita. Sé que estás aquí porque confías en esta página para escoger los profes de tus cursos. Pues bien, te cuento que a veces hay gente por acá que solo busca manchar la imagen de los profesores sin razón. Eso está pasando con este profe. Por fa no te dejes engañar. Masis es super :)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-08-09T00:00:00+00:00'::TIMESTAMPTZ, '6c2d837870c65f82276f73220d9fb48f28770493b2fc94db64c913f97b678edb'::TEXT, ARRAY[1671, 923]::BIGINT[]),
    (496::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f418d8084ca42b56275d475c38373c9504b2a96e2c4d7160b11ea1b0bf11d83e'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor, genera un ambiente sano en la clase y realmente le gusta enseñar. Masís siempre es una buena opción'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2021-07-21T00:00:00+00:00'::TIMESTAMPTZ, '4897cd7d20c46b5e8392daa6c872366be8bf0c5c8289fc6ef6198daaec0e0e4b'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Es un excelente profesor, la verdad ayuda mucho, saque 100 en todos los exámenes gracias a que al hacer las practicas y fallar el siempre ayuda y me hacia ver los errores, es muy buena gente, dispuesto a ayudar, no lo piense, si puede matricularlo hagalo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Inspirador']::TEXT[], '2021-07-06T00:00:00+00:00'::TIMESTAMPTZ, 'd0ca7d27c8cf04dd2190a78e522f5848d058feaef9602d4992c1aa86cc805575'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'El profe es súper buena persona, siempre dispuesto a ayudar al estudiante y de verdad le interesa que uno aprenda. En modalidad virtual, se lució con las clases, siempre claras, más que suficiente para las tareas de cátedra y exámenes; no tenga miedo de preguntar, él siempre responde con amabilidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-30T00:00:00+00:00'::TIMESTAMPTZ, '84d1c4388ec857c840c2719792e239b0af36907ccc90c4c729f056f0619d3c8d'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor, definitivamente con él no quieres que termine el curso, explica claro, por telegram siempre contesta las dudas, ayuda mucho, uno de los mejores profes.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, '6d568160ceb6fb6998fd0082855ca66168de0da947e4154158fac9e35d105cb9'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Es el mejor profe que he tenido, sus clases son súper claras y en consulta también. Excelente profesor. Un profe muy pura vida.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'a77cd88f3c3ac25c7e571c12943205723ffd083d155e1fb62911a62159c6c37a'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor profesor que tiene la cátedra sin duda alguna, el profe le da puntos por procedimiento y ayuda siempre que usted tenga una duda, (parece serio, pero es super buena nota)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'e0891ca2c5d01202faf32358584775ff4f7e3669dadc2b106874399530c6be84'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor profe, sus clases son bastantes buenas y son ejemplos de nivel del examen, da consejos sobre los ejercicios, en fin, lo recomiendo. Los exámenes de la cátedra pues son de un nivel que hay que tener cuidado, pero si se pasa, relax. Las tareas ayudan mucho para examen HÁGALAS A CONCIENCIA'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Da crédito extra']::TEXT[], '2021-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'c17f7424cde76d894071c0c09f44d42f48139ee69bde980d8ff194c1ea3743b2'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Todo un crack, de los mejores profesores que hay en el TEC. Es super simpatico, da bastantes ejemplos al nivel de examen y explica super bien. Si tiene la oportunidad de meter algun curso con el, no lo dude'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'a184d646e9b7652e18c5b4ddcbe9bc80b5acc081a40bd55702f510dcf806fa95'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El mejor profe, ayuda con todo y siempre se preocupa por los estudiantes. Además explica demasiado bien. Lo recomendaria a todo el mundo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, 'c33868d1f2faab02cc292e59b015a0a024317a0aab235d1d215199913ca2c70f'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, '¡El mejor profe de mate que he tenido! Ayuda demasiado a los estudiantes, las clases y ejemplos que hace son sumamente claros y útiles para hacer las evaluaciones cátedra y sacar notas buenas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-03-07T00:00:00+00:00'::TIMESTAMPTZ, '82968acfb0b33a5eb84d8ad6a8e9f170642c3ffff1e6b5f0dfda56f0e6344d0a'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'El profe te prepara muy bien, para los exámenes de cátedra, aún así siempre es mejor revisar las prácticas por si acaso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Brinda apoyo']::TEXT[], '2021-02-08T00:00:00+00:00'::TIMESTAMPTZ, '77f0525d8ae8ca0a66234cb8bd02dc2c12f4cd8c2ec7b4df41c7c9335943c2f1'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Es el mejor profe de mate! Explica súper bien y si a uno le pasa algo es muy comprensivo al respecto para reprogramar cosas o dar otra oportunidad'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '5eb0ab4df01d900fac3bd61bd0b79a3e4e105edd17b8568b289c7c2f772b3ddb'::TEXT, ARRAY[1026]::BIGINT[]),
    (496::BIGINT, 'De los mejores profes. Explica la materia muy bien en corto tiempo, de una forma que uno entiende todo. Mantiene las notas actualizadas. Siempre contesta las consultas rápido. Sin duda vale la pena matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-31T00:00:00+00:00'::TIMESTAMPTZ, '31d1a7b1c161d9c082f70eeb3fe8662199df84b53372898c1e6c592bfa1bacbe'::TEXT, ARRAY[1026]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor, se preocupa por que uno aprenda verdaderamente. Es muy accesible en virtualidad, siempre está dispuesto a ayudar inclusive fuera de su horario laboral. Maneja muy bien la materia.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-28T00:00:00+00:00'::TIMESTAMPTZ, '033d143c4ab6017d835e56a862903d3b7eb8e184a0a9ed452ce86066f33e5cf9'::TEXT, ARRAY[1026]::BIGINT[]),
    (496::BIGINT, 'El mejor profesor que he tenido, matricule con él sin dudarlo, hacer ver las cosas de manera fácil y se preocupa mucho por los estudiantes, es una teja de persona.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-10-04T00:00:00+00:00'::TIMESTAMPTZ, 'b9d1f993c940c66ab40dc27a10f578dc03934485dd863be96583b551dd24e0de'::TEXT, ARRAY[634]::BIGINT[]),
