    (496::BIGINT, 'Excelente profesor, si tiene la posibilidad de meter cualquier curso con él, hágalo a ojos cerrados. Hace ver la materia más difícil de manera muy sencilla y las clases se sienten cortas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '7d05e6070ca8d871b9eeb0883e14cdb8a9a6c73876cfe842db49657f55321e4d'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'd467e406b86ed6e78a806d184e1cd0f88f617e86c438e75a37b66240572a0a15'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Masis es Dios en la Tierra. Me dan hasta ganas de pasarme de carrera. Las mejores clases de matematicas que haya recibido. Ese mae monta una iglesia mañana y yo lo sigo. Amen'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Clases excelentes']::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, 'a70fe2a1ac0bc571748efe5eb7dc240337838ce9fd3a8c82c23d6063868e1503'::TEXT, ARRAY[1050, 1049]::BIGINT[]),
    (496::BIGINT, 'El mejor, es increible como profesor y como persona. Quiere que todos entiendan y pasen, explica demasiado claro y es demasiado comprensivo. Todo lo que dicen de el es cierto. Si puede meter con el no lo dude.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '88dbad547dc4e16a5aedd02311ef8a469e99109bf7038bfdf9598b827efeaee7'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Las clases son súper amenas, el profe se esfuerza para que todos entiendan y sus explicaciones son excelentes. El mejor profe!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '858cc5df08bf2a6e7df0027b3e92ba344bb4c89de395adb0292067b2fddd27f1'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Simplemente un crack!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '423b10e177ade09b314dcc2c83f260d6a561fe875e82d71bb2cf2d9a55d04ed7'::TEXT, ARRAY[1669]::BIGINT[]),
    (496::BIGINT, 'Masis es simplemente el mejor profesor que hay, si tiene oportunidad de matrIcular con el no lo dude. Para la modalidad virtual fue excelente , las clases eran muy provechosas y no hace falta estudiar mucho . Como persona es excelente y se preocupa porque los estudiantes aprendan.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-18T00:00:00+00:00'::TIMESTAMPTZ, 'b05bce86cd99e787dc2bd81c93d43942075ef8d6a21ef98ca457c2722a21765e'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Simplemente increible para la modalidad virtual, da justo lo que se necesita para pegar 100 y con excelente claridad y clases entretenidas.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'e881df4bd54ed5b2b2f0003fd58cd5d76b343015f2f3592e6047d857913dc84d'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Excelente profe, muy creativo para dar las clases y despeja cualquier duda'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Clases excelentes']::TEXT[], '2020-08-15T00:00:00+00:00'::TIMESTAMPTZ, 'b7fe4d4e368ce7b3a01f245a621a0f38b2d81c1c2bb7281d0c22d6d95b2fa144'::TEXT, ARRAY[634]::BIGINT[]),
    (496::BIGINT, 'Va un paso más allá de lo que se le pide a un profesor. Es un sol. Nada que no se haya dicho ya. Tiene tablet, eso es una ventajota en cursos virtuales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, '3f5431435e571150e860593be7b095877170b5c466b1f98d54806e32ad278eca'::TEXT, ARRAY[1669]::BIGINT[]),
    (496::BIGINT, 'Es una excelente persona y profesor. Sus clases son demasiado provechosas, casi que no hace falta estudiar si se pone atención en sus lecciones. Califica justo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Da crédito extra', 'Clases excelentes']::TEXT[], '2020-08-09T00:00:00+00:00'::TIMESTAMPTZ, 'af8987861234ef5bb651466051743315df024ccf1cdde608d8ac45cb2951039b'::TEXT, ARRAY[1647]::BIGINT[]),
    (496::BIGINT, 'El mejor profe de matemáticas que he tenido, se preocupa por sus estudiantes y explica muy bien la materia, es claro y da ayuda extra que facilita el resolver los ejercicios para el examen. Si puede matricule con él y le aseguro que no se va a arrepentir.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-08T00:00:00+00:00'::TIMESTAMPTZ, 'be4811e5e92414daae9d08d251cd2a64c62bed497bb4ba4e90089f7d84f2a35f'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'De los mejores profes de matemática que he tenido. Explica súper bien, es super paciente y se preocupa porque los estudiantes de verdad aprendan y entiendan. Es muy pura vida y hace que la gente disfrute su curso. Excelente profe, súper recomendado!!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-07T00:00:00+00:00'::TIMESTAMPTZ, '85945aedb3170ca0262da5b7fcf6550895855783d1509bd3831b249f58307269'::TEXT, ARRAY[1669]::BIGINT[]),
    (496::BIGINT, 'Es el mejor profe que he tenido, tiene mucho conocimiento sobre los temas y lo sabe enseñar, las clases son muy provechosas. Si usted necesita ayuda con algún ejercicio el profe de fijo lo va a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Clases excelentes']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '7c1c96ddeb1afca824ca8f76cba53a33e949a5fc1613f24da72976b75ffab761'::TEXT, ARRAY[1669]::BIGINT[]),
