    (496::BIGINT, 'EL MEJOR PROFE! Hace que uno vea cualquier vara matemática como lo más fácil del mundo, en semestre normal es excelente y si piensa llevar verano con él.... NO LO DUDE!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-24T00:00:00+00:00'::TIMESTAMPTZ, '93faaf03b87bc908ba358682ed057e94b85da3c4b8eb5765ec855b6ff687bf75'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'DIOS MASíS Explica super bien, responde todas las dudas. Se pone la mano en el corazón para calificar y los quices que hace son super avisados y manejables. En consulta es genial. Volvería a llevar con él todo lo que pudiera'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2018-01-18T00:00:00+00:00'::TIMESTAMPTZ, '78995a6304ada9d0b60671809c99a8ca6f2c6a6f5a4a53b601f6bf32fd5836e0'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'Hace ejercicios para todos los casos posibles y ayuda si uno no entiende. Algunos quices los deja para la casa y explica todo demasiado bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-16T00:00:00+00:00'::TIMESTAMPTZ, '746ab4ca8b75e341f006caf6b96359b4a7d41baf00a579fcb796b836630926f2'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'LO MEJOR QUE LE PUEDE PASAR EN EL TEC!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-04T00:00:00+00:00'::TIMESTAMPTZ, '6c47ff3c37baf3a30482b203bc75c418802f86908df0010a7cb70f12d6f37477'::TEXT, ARRAY[2439]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor de matemáticas. Su forma de explicar y el orden de la lección hacen que el curso sea muy fácil, hace ejercicios un poco elevados con respecto a los exámenes para facilitar el aprendizaje de los contenidos del curso. Matriculen a ojos cerrados con Cracksis!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-11T00:00:00+00:00'::TIMESTAMPTZ, '6c4289275ff43c79515111418cd03bee8abf7a75deb55a616de9af2d272dabb8'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'De los mejores profes del TEC. Hace que un curso tan difícil como cálculo se vuelva fácil. Explica super claro, ayuda en notas y los quices que hace son fáciles. 100% recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-12-04T00:00:00+00:00'::TIMESTAMPTZ, 'cd934e2092cb4fe12cd72acaf8c6f58b714c0db53a8dd19d8fc4d7e1ed997409'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es un muy buen profe! Es muy tuanis y explica bien. Hace pocos quices y ayuda bastante en consulta. En general es un excelente profe! Volvería a matricular con él. 100% recomendado.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-01T00:00:00+00:00'::TIMESTAMPTZ, '06f7ef8d6a52f4adc4e02bea74f3ad26c59b1cca66f3350907caf5917af4311c'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'Es un excelente profesor y buena gente, hace pocos cuices y practicamente nada de tareas pero con solo ir a las clases ya uno entiende super bien y siempre deja practicas para examen opcionales.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, 'ea5dbc640ead8e9ab8385541fabb04953167157818789a38074ba199b97f18d6'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'Excelente profe. Super buena gente con el estudiante, explica demasiado bien la materia, además de que si un estudiante no entiende él vuelve a explicar la materia sin ningún problema. Hace pocos quices y pocas tareas y en consulta es muy pura vida. No dude en matricular con él.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-30T00:00:00+00:00'::TIMESTAMPTZ, '49c9dad2520c3c606739b916aea7249c0ee67ff2f1671ae95e84e31367623587'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor, 100 % recomendado. Da ejemplos en clase similares a los del examen y no dude en preguntar si no entiende algo, el profe siempre le aclara las dudas y trata de explicar de forma que todos comprendan la materia. Si es su primera vez, no dude en matricular con él...'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-11-24T00:00:00+00:00'::TIMESTAMPTZ, 'a54a8490b7161f6b88b3864bfb756d5180bc0341a1e8244efb5f00a61e19cdae'::TEXT, ARRAY[563]::BIGINT[]),
