    (496::BIGINT, 'Él es demasiado buen profe, es súper buena gente y muy pura vida. Hace los quices lo normal y califica lo justo. Si usted no entendió algo, él le vuelve a explicar todas las veces que sea necesario. Es muy bueno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-09-24T00:00:00+00:00'::TIMESTAMPTZ, '89928644ff56691f0bc7214dc7429b9b621cacc59426bd24eda3b4707b89022a'::TEXT, ARRAY[563]::BIGINT[]),
