    (496::BIGINT, 'Masis esta sentado a la derecha de Murillo, juntos los dos soy los reyes y señores de la escuela de mate. Larga vida a Masis!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2017-01-23T00:00:00+00:00'::TIMESTAMPTZ, 'efdedf828c2aed085e14edc6d1912e72d1a3af07ea72c036e2abf532ff848c29'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'No sé que tan bueno sea Murillo aun pero para mi Masis es EL crack! Vacila con los estudiantes, los ejemplo son muy parecidos a los del examen, si se apiada de su alma hace quizes grupales o casi siempre son para la casa. SUPER RECOMENDADISIMO'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2017-01-19T00:00:00+00:00'::TIMESTAMPTZ, 'edb5f21532da65fea29463014b08bdabc155bdef8112306a7e14084e97a48df0'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-18T00:00:00+00:00'::TIMESTAMPTZ, '3a9421eabfd688092d8a248b8b380977eb95e6333c57286fd1469658d88a173d'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es un excelente profesor, explica súper bien, se interesa por los estudiantes y muestra interés por que les vaya bien, la mayoría de los quices son para la casa y son muy fáciles, califica justamente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-14T00:00:00+00:00'::TIMESTAMPTZ, '6d63d1252898979bc80f370954578167ae07d7a9238e27f60252867d1a6eb427'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-12-06T00:00:00+00:00'::TIMESTAMPTZ, '5ef1b28008e92fcdd821725fbb5c237ee8c609e9d0772b0894ce086f9ccdfd8f'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'El.mejor profesor de la escuela de mate, es muy claro, no falten a clases porque los ejemplos que dan son sumamente parecidos a los del examen. Ayuda mucho y considera al estudiante. Simplemente excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2016-11-03T00:00:00+00:00'::TIMESTAMPTZ, '671d51edf004e95a81438f2eb3d5739c5a1b63806434543748e9c26ad03ff254'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es increíble persona y el mejor profe que he tenido en el TEC. Explica muy bien, es muy ordenado, las clases son super amenas y si usted estudia y va con todo al día de fijo pasa con excelente nota. El profe es atento y es buenísimo explicando. No dude en matricular con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2016-10-27T00:00:00+00:00'::TIMESTAMPTZ, '021bb50416fb3e5b9d4c23598f0fff7e6ac6f5f8d9463d0443cc1969b45bfd26'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'No es por idealizar ni exagerar, pero este señor tiene todas las cualidades del maestro óptimo. Explica sumamente claro, repite cuantas veces sea, hace repaso de la clase anterior al inicio de la clase, es revisa fácil, ayuda mucho...ideal!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2016-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'adf6c7e7d55b5d12363d00a88383e3ceedd4f2d880ed09f601adb6b6d95e65b1'::TEXT, ARRAY[605]::BIGINT[]),
