    (496::BIGINT, 'No hay palabras, Masís es el mejor profe de la escuela de mate (junto con reyman). Sin duda recomendado al 100% Explica hasta que todos entiendan, trata bien a los estudiantes, no maltrata con los quices ni tareas, da ejemplos con nivel superior al examen y las practicas son excelentes para estudiar'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-04T00:00:00+00:00'::TIMESTAMPTZ, '617861ddd07e6f1e55e783293b66fc6592e79b753e3954a4256360afb477b45b'::TEXT, ARRAY[605]::BIGINT[]),
