    (496::BIGINT, 'Masis es uno de los mejores profesores que existen. Explica super claro, califica facilillo y es SUPER paciente...o sea, hasta uno se impacienta de lo paciente que es el jaja. Explica suavemente, repetidamente.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'd6a33ecdfcecc44c49cd9b89d34472e559740ae3498d3206bf5e0ec7e7f8998c'::TEXT, ARRAY[1667, 1647]::BIGINT[]),
    (496::BIGINT, 'Excelente profesor. Explica paso a paso los procesos, además de brindar ayuda y asegurarse que todos entiendan. Evalúa el curso de la manera correcta.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '4a88e243f2a6be7dc0a66c949ab25d0397674166aa6c8d4e6959dd3890175fd2'::TEXT, ARRAY[563]::BIGINT[]),
    (496::BIGINT, 'Lo mejor de la vida. Explica súper bien y es muy profesional'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '5f9bc977bb9e0e73f956f85508981afa7ce83c68e874bbd746b6cd3a69f3b7e8'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Parece increíble que existan personas que se pongan a difamar a los profes que son realmente buenos, esto hace que la página pierda credibilidad. Lástima que el profe borró los videos de su canal de youtube para que se den cuenta que es excelente, explica bastante claro y es muy comprensivo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-03T00:00:00+00:00'::TIMESTAMPTZ, '722baf76d10f4784e2e30c597fecd63af6acdc7309fd9c747770806093ea3a00'::TEXT, ARRAY[1672]::BIGINT[]),
    (496::BIGINT, 'Llevé ED en virtual el II S 2021 y me conecté a todas sus clases y estos comentarios son falsos. El profe explica super claro y las veces que sea necesario, envía los apuntes un día antes y es muy ordenado y a todos los trata por igual. Pregunten en estudiantes tec para referencias y no crean esto.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'a4c9285a13a36576b1c23ce102d31fb509a5e99b58ccdd5aa8d9f3b1971720e8'::TEXT, ARRAY[1672]::BIGINT[]),
    (496::BIGINT, 'Es un sucio, hace actos obscenos en clases, en consulta toquetea a las guilas, y no sabe explicar.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-26T00:00:00+00:00'::TIMESTAMPTZ, '2ba7ee3669b44e01cc6ef272eab225e2bf2218c3152fb255f289b42756a676fe'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'No metan con este profe porque uno va y le ofrece pasar el curso a cambio de sex0 y listo. Además hasta donde sé, ningún hombre le ha pasado un curso.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-23T00:00:00+00:00'::TIMESTAMPTZ, '9d16998ab5ac0452f9ffde7a3cd04adf4c6cba1e9b73d6221d39c4cfacb3057b'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'Que les puedo decir. Ningún hombre pasa con él, se manda a las guilas en el aula y en moteles de mala muerte. Huele feo, llega ebrio, y en ocasiones cierra la puerta del aula y hace ahí sus necesidades, increíble como sigue trabajando ahí.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-13T00:00:00+00:00'::TIMESTAMPTZ, '19f8ef3046f0fcb415f74f2a6f21d76abeae538228e9d330a3b22769bb72ddff'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'Soy mae hetero y le pasé un curso, el profe explica bien y te atiende consultas casi q 24/7. Pero si sos güila y medio bonitilla, xq tenes q ser bien fea para q te rechace jaja, xq una sola propuesta y la ética moral y profesional se le olvida. Una compa pasó Ecua dando su esfuerzo en el Tu y Yo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación', 'Brinda apoyo']::TEXT[], '2025-08-13T00:00:00+00:00'::TIMESTAMPTZ, '0d4028d27d6a13aaf648ea655bc4cd487a671978e54fa6f11834c8fb554bb033'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'Muy buen profe, coqueto pero buen profe ja ja El profe no te hecha el cuento pero facilito cae, con solo que vayan a consulta, eso les abre oportunidades para poder llegarle. Técnica que varias hemos aplicado y así le pasamos el curso.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-07-26T00:00:00+00:00'::TIMESTAMPTZ, '51d208820062a44dba955820417dcf54f9c39d8956b47fce4805f37f0eb88c03'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Es muy buen profe. Es el segundo curso que llevo con él, y él no anda detrás de las güilas, pero si es como el agua jaja porque no se le niega a nadie, y si cae fácil con las estudiantes mujeres y lo digo con conocimiento de causa.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-01T00:00:00+00:00'::TIMESTAMPTZ, '47fff985e950d251606a16781f7e73d729fdab205ff319bd50adc098715fc7fe'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'El profesor explica demasiado bien, es organizado con sus apuntes y material de clase. En verano nos permitió llevar apuntes, lo que fue una salvada.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-02-09T00:00:00+00:00'::TIMESTAMPTZ, '06e87e5386b13f35f8305fc472913e0b21338c97ab2714b8c9758157928e8303'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'De los mejores profes que he tenido honestamente. Explica con claridad y sencillez, es decir, va directo al grano, explica las cosas como son y te dice aspectos importantes de cada operacion para que tomes nota. No son de esos profes que te da un sermon para que te aburras (Reprobé con un profe asi)'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-03-08T00:00:00+00:00'::TIMESTAMPTZ, '59a394d3cb0cba572f416ee6f247962d3132acf785a54493b47d529da253b30b'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'El mejor profe para superior, las clases son muy claras, las evalvuaciones acorde a la lo visto en clase y está dispuesto a ayudar y responder dudas. No duden en matricular con él'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2023-06-21T00:00:00+00:00'::TIMESTAMPTZ, '4604e5d919a1ebb8bfb54a6f4d3ebf3b526c30f69a066c7d692f2d658e707e22'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Valeria Villalobos amiga si tenes conocimiento de causa que el profe da crédito extra ponelo públicamente o denuncialo y no seas tan ardida e inmadura de poner cosas falsas del profe solo porque no te hicieron caso. Eso hace que la página pierda credibilidad.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-11T00:00:00+00:00'::TIMESTAMPTZ, 'ccc7c7ff5e0d93c4b8c9ee20f7dd6b56d031f020ac5bcae90c41273e239399a5'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (496::BIGINT, 'Me encanta como disfrutaste tu regalo, para mi también lo fue, tbn lo disfruté amor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-17T00:00:00+00:00'::TIMESTAMPTZ, '4ef31e169f5aeddf0e009978d64fe117468fae84248accc8388988b42b6c8ab2'::TEXT, ARRAY[1667, 1647]::BIGINT[]),
    (496::BIGINT, 'Feliz Navidad profe, te amo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Clase fácil', 'Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2023-12-24T00:00:00+00:00'::TIMESTAMPTZ, '64746fb88cec19bb38a4801e1f04a13e72b76301c472fb7b4a6a2a342590d03d'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Pseudoprofesor, no sirve para nada, no da clases, todo el grupo se quedó. Lo único que hacía era ligarse a las guilas por el grupo de telegram, porque como bien dice mi amiga Villa, telegram para mí y whatsapp para la esposa.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('20','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-05T00:00:00+00:00'::TIMESTAMPTZ, '227be7c94abb767a0db4a32cc39fb2916c7e04a656e22eb10ba1aa98dc24bb10'::TEXT, ARRAY[968]::BIGINT[]),
    (496::BIGINT, 'Profesor que se metió con mi amiga la salvadoreña y la mexicana. De verdad no les recomiendo llevar verano ni ningún otro curso con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '99ccad85f68aae54d0beb8accc9608cd2aee65e0ae369ee63734edd3999ea8ee'::TEXT, ARRAY[1671]::BIGINT[]),
    (496::BIGINT, 'Un ras profe, el mae es muy tranquilo, explica super bien, brinda mucho apoyo si se le pregunte y sus evaluaciones (tareas, exámenes) son muy fáciles'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-16T00:00:00+00:00'::TIMESTAMPTZ, '3c480e99ad09eef7112a7e70459e41e9e2590911ecd45ba7393b0f2159aa8baa'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'El curso es corto, parece que se estira para que dure las 16 sem, entonces hay semanas que con la clase virtual basta ( hace que el semestre sea más chill ) . Los quices son presenciales. Estudie los ejercicios que hace y pone, porque se parecen mucho a los quices y examenes.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2025-06-27T00:00:00+00:00'::TIMESTAMPTZ, '6cb951b87c0fce6dac61ca84a8ba4d393e9a9a10880e71798707e4f129830642'::TEXT, ARRAY[1057]::BIGINT[]),
    (496::BIGINT, 'Súper buen profe!'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2025-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'e31b8d68aca140696168227281857bc18479cc078fc03a16e8a8f62aa94f0134'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Las clases de él son muy buenas, la verdad hace ver la materia con facilidad.Es super estricto con esto del plagio, pero si usted es de los que no copia o usa chatgp no tiene de que preocuparse.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2024-01-18T00:00:00+00:00'::TIMESTAMPTZ, 'a84fdffde9b22585b071fedf5f93b65d09c3e787658b3d340d843ff99ddce2d4'::TEXT, ARRAY[968]::BIGINT[]),
    (496::BIGINT, 'Así que con café logro ser una de las de temporada. La pobre boba de ambiental nunca lo logró ja ja ja. Todo bien en casa? Ja ja ja'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'a9ef14e41b6f1b07001b67df4baf23de694d8ca26304f3e001c3d679cee4fa93'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (496::BIGINT, 'Viejo verde'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('55','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-18T00:00:00+00:00'::TIMESTAMPTZ, '973192cc109c5abf0918f0bc28f9f01041dde08054a923b2d8967b19a335874c'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (496::BIGINT, 'Tenían razón en todos los comentarios malos. Profesor que no da clases, nos puso a leer consignas que no sirven y les envió un mensaje a las guilas diciéndoles que él les da crédito extra a cambio de intimar con ellas. Con conocimiento de causa lo digo ja ja ja'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('45','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-10T00:00:00+00:00'::TIMESTAMPTZ, '2352bcdb2f51ace301610251d55b8ec67c342de262ff8119b2856a71e72f9ab3'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Excelente profe, se esfuerza para que uno aprenda, es gracioso, sus quices suelen tener ejercicios extras o algun detalle diferente para que uno gane puntos. Si quiere pasar CDI lleve el curso con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2025-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'c1ab8233f93fb60744d53fc5200842edd99e54e1321f8d166b420c2b391df25a'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'María Jesús amiga no seas tan mordida por lo que puse. Como vos y yo sabemos, te duele en el alma no haber podido con el profe. Y si solo fue por aprovechar tu temporada, por qué aún le escribes a la esposa?? Ja ja ja punto para mí, z0rra.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-15T00:00:00+00:00'::TIMESTAMPTZ, 'a6ce2e7a33d53e3c825a4b43909da8ef37e3d8f18653c3e9a4e3bec5ae955f82'::TEXT, ARRAY[1631, 1629]::BIGINT[]),
    (496::BIGINT, 'Soy chica matec, en la carrera me conocen como Lorna la horna. El año pasado que el profe dio cálculo 3 se presentó como todo un soltero disponible a todo. Yo me le metí, pasé el curso, pero les digo una cosa chicas, le huele feo por allá y la tiene tan pequeña que tiene que usar un pene postizo.'::TEXT, 10.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('5','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'c88ab122bc42d7433d8fd34e42ed90976bee80b9ceeba041ff867ff0be987dbf'::TEXT, ARRAY[1667]::BIGINT[]),
    (496::BIGINT, 'Excelente profe'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-10-28T00:00:00+00:00'::TIMESTAMPTZ, '99101b81ce81d8240792d168cf06e856439edc1ce2e6947801a82e7ab6530777'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Es excelente profe, si quiere pasar CDI matricule con el. La materia no se termina sintiendo tan pesada. Brinda muchas ayudas y es una teja'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2026-07-19T00:00:00+00:00'::TIMESTAMPTZ, '6701bfdfe8e2e5882359b61f709b1eadd535912f9b00f3cbadcc10f1b3504a28'::TEXT, ARRAY[605]::BIGINT[]),
    (496::BIGINT, 'Contexto plis jaja'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('10','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Da buena retroalimentación']::TEXT[], '2025-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'd07bfff4a102024289ad501f0fc77b73649585e921afe9a4175ac9c9d9b6657f'::TEXT, ARRAY[923]::BIGINT[]),
    (496::BIGINT, 'Cálculo diferencial e integral 2025, motel tu y yo, Masis pasó a otra estudiante por sexo, que lo diga BJ. Pronto les pondré los nombres de todas las maes a las que Masis ha pasado por sexo.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-09-25T00:00:00+00:00'::TIMESTAMPTZ, 'dc3045c88353720a17def1af7ee48e16b76310f52872536a948dbf12f3d1b1d1'::TEXT, ARRAY[605]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
